-- PT121-S1-Q18. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT121-S1-Q18$batch10$ AND q.stimulus=$batch10$Advocate: You claim that it is wrong to own gasoline-powered cars because they pollute too much; you have an electric car, which pollutes far less. But the company that made your car also makes millions of gasoline-powered vehicles, so your patronage benefits a producer of products to which you object. Thus, if you are right about gasoline-powered cars, you should not have your electric car either.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, would most help to justify the advocate's reasoning?$batch10$ AND q.correct_choice=$batch10$D$batch10$) THEN RAISE EXCEPTION 'Question changed: PT121-S1-Q18'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT121-S1-Q18$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S1-Q18'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT121-S1-Q18$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$If owning gasoline-powered cars is wrong, you shouldn't own your electric car either.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The company that made your electric car also makes millions of gasoline cars, so buying from it supports a maker of products you object to.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The advocate's point is about support. Buying the car supports a company that does what you think is wrong. The principle has to say that you shouldn't support an organization that does something you believe is wrong.$batch10$), (3, $batch10$Goal$batch10$, $batch10$One should not support an organization that does anything one believes is wrong.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT121-S1-Q18$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This says a less harmful action can still be wrong. The advocate's reason isn't that the electric car is harmful. It's that buying it supports the gasoline-car maker.$batch10$), ($batch10$B$batch10$, $batch10$The electric car pollutes far less, so this principle would, if anything, approve of buying it.$batch10$), ($batch10$C$batch10$, $batch10$This says when one should buy something. The advocate is arguing about when one should not.$batch10$), ($batch10$D$batch10$, $batch10$If you think gasoline cars are wrong, the company does something you believe is wrong. Owning its electric car supports it, so by this principle you shouldn't own it.$batch10$), ($batch10$E$batch10$, $batch10$This targets companies with no sound products. This company makes the electric car, which pollutes far less, so the principle doesn't reach it.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT121-S1-Q18$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
